int64_t getSiz(int64_t i, int64_t z) {
    if (i == 1) return 2;
    if (i % (2 * z - 2) == 0) return 1;
    if (i % (2 * z - 2) <= z) return (i % (2 * z - 2));
    return (2 * z - 2) - (i % (2 * z - 2)) + 2;
}

int64_t getZ(int64_t l, int64_t r, int64_t z, int64_t a[]) {
