    int y_xor = 0;

    for (int i = 0; i < x_coords.size() - 1; i++) {
        x_xor ^= (x_coords[i + 1] - x_coords[i]) - 1;
    }

    for (int i = 0; i < y_coords.size() - 1; i++) {
        y_xor ^= (y_coords[i + 1] - y_coords[i]) - 1;
    }

    if ((x_xor == 0) && (y_xor == 0)) {
        cout << "SECOND" << endl;
