            int gap = -1;
            for (int i = 0; i < x_coords.size() - 1; i++) {
                if ((x_coords[i + 1] - x_coords[i]) > 1) {
                    gap = i;
                    break;
                }
            }

            int start = x_coords[gap] + 1;
            int end = x_coords[gap + 1];

            cout << start << " " << 0 << " " << start << " " << m << endl;
        } else {
