    while (q--) {
        ans = 0;
        int len;
        cin >> len >> c;
        init(n);
        for (int i = 1; i <= 26; i++) f[i] = 0;
        for (int i = 1; i < n + 1; i++) f[s[i - 1] - 'a' + 1]++;
        for (int i = 1; a[i] <= n; i++) {
            int tot = 0;
            for (int j = 1; j <= 26; j++) {
                if (j != c[0] - 'a' + 1) {
                    tot += min(f[j], len);
                }
            }
            int cnt = 0, l = 1, r = i, mid, slen;
            while (l <= r) {
                mid = (l + r) / 2;
                slen = a[i] - a[mid] + 1 - (i - mid);
                if (tot + slen <= len) {
                    cnt = max(cnt, i - mid + 1);
                    l = mid + 1;
                } else {
                    r = mid - 1;
                }
            }
            ans = max(ans, cnt);
            memset(f, 0, sizeof f);
