                    for (int y = l + 1; y < n; y++) {
                        int cnt = 0;
                        for (int p = j; p <= x; p++) {
                            for (int q = l; q <= y; q++) {
                                if (((i >> (p * n + q)) & 1) == 1) cnt++;
                            }
                        }
                        if (cnt >= k) ok = false;
                    }
                }
            }
        }
        if (ok) ans = add(ans, dp[i]);
    }
