using namespace std;

const int maxn = 1005;

struct Edge {
    int to, next;
};

Edge edges[2 * maxn];
int head[maxn], cnt;

void addEdge(int u, int v) {
    edges[cnt].to = v;
    edges[cnt].next = head[u];
    head[u] = cnt++;
}

vector<int> G[maxn];

int dfn[maxn], low[maxn], clk;
int stk[maxn], top;
int scc_cnt;
int belong[maxn];

void tarjan(int u, int from) {
    dfn[u] = low[u] = ++clk;
    stk[++top] = u;
    for (int i = head[u]; i != -1; i = edges[i].next) {
        int v = edges[i].to;
        if (dfn[v] == 0) {
            tarjan(v, u);
            low[u] = min(low[u], low[v]);
        } else if (belong[v] == 0) {
            low[u] = min(low[u], dfn[v]);
        }
    }
    if (low[u] == dfn[u]) {
        scc_cnt++;
        while (stk[top] != u) {
            belong[stk[top]] = scc_cnt;
            G[scc_cnt].push_back(stk[top]);
            top--;
        }
        belong[u] = scc_cnt;
        G[scc_cnt].push_back(u);
        top--;
    }
}

