        if (dfn[i] == 0)
            tarjan(i, 0);

    for (int i = 1; i <= n; i++)
        for (int j = i + 1; j <= n; j++)
            if (g[i][j] && belong[i] == belong[j])
                return cout << -1, 0;

    for (int i = 1; i <= n; i++) {
