using namespace std;

struct Edge {
    int u, v;
    Edge(int u = 0, int v = 0) : u(u), v(v) {}
    bool operator < (const Edge& other) const {
        if (u != other.u) return u < other.u;
        return v < other.v;
    }
};

vector<Edge> ans;
vector<vector<int>> graph;
vector<int> deg, seen;

void dfs(int u) {
    seen[u] = 1;
    for (int v : graph[u]) {
        if (!seen[v]) dfs(v);
    }
}

void addEdge(int u, int v) {
    ans.push_back(Edge(min(u, v), max(u, v)));
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    graph.resize(n + 1);
    deg.resize(n + 1, 0);
    seen.resize(n + 1, 0);

    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        graph[u].push_back(v);
        graph[v].push_back(u);
        deg[u]++;
        deg[v]++;
    }

    for (int i = 1; i <= n; i++) {
        if (deg[i] > 2) {
            cout << "NO\n";
            return 0;
        }
    }

    for (int i = 1; i <= n; i++) {
        if (!seen[i]) {
            dfs(i);
            if (graph[i].size() == 0) {
                addEdge(i, i);
            }
        }
    }

    vector<int> odd;
    for (int i = 1; i <= n; i++) {
        if (deg[i] == 1) odd.push_back(i);
    }

    sort(odd.begin(), odd.end());

    for (int i = 0; i < odd.size() / 2; i++) {
        addEdge(odd[2 * i], odd[2 * i + 1]);
    }

    cout << "YES\n";
    cout << ans.size() << '\n';
    for (auto e : ans) {
        cout << e.u << ' ' << e.v << '\n';
    }

    return 0;
}

#include <iostream>

int count_tuples(int n) {
    int count = 0;
    for (int a = 1; a <= n; a++) {
        for (int b = 1; a * b <= n; b++) {
            int c = n - a * b;
            if (c > 0) {
                count++;
            }
        }
    }
    return count;
}

int main() {
    int n;
    std::cin >> n;
    std::cout << count_tuples(n) << std::endl;
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef pair<ll, ll> pll;

const ll MOD = 1e9 + 7;

ll gcd(ll a, ll b) {
    if (a == 0)
        return b;
    return gcd(b % a, a);
}

ll powmod(ll a, ll b, ll mod) {
    ll res = 1;
    while (b) {
        if (b & 1) {
            res = res * a % mod;
        }
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

void solve() {
    ll n;
    cin >> n;

    vector<pll> points(n);
    for (auto& point : points) {
        cin >> point.first >> point.second;
    }

    vector<set<ll>> bad(n);
    for (ll i = 0; i < n; i++) {
        for (ll j = i + 1; j < n; j++) {
            if (points[i].first * points[j].first + points[i].second * points[j].second == 0) {
                bad[i].insert(j);
                bad[j].insert(i);
            }
        }
    }

    vector<ll> dp(n);
    for (ll i = 0; i < n; i++) {
        set<ll> banned;
        for (auto& v : bad[i]) {
            banned.insert(v);
        }
        for (auto& v : bad[i]) {
            for (auto& u : bad[v]) {
                banned.insert(u);
            }
        }
        ll cnt = 1;
        for (ll j = 0; j < i; j++) {
            if (banned.find(j) == banned.end()) {
                cnt = (cnt + dp[j]) % MOD;
            }
        }
        dp[i] = cnt;
    }

    ll ans = 1;
    for (auto& c : dp) {
        ans = (ans + c) % MOD;
    }
    cout << ans << '\n';
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll t = 1;
    // cin >> t;
    for (ll i = 0; i < t; i++) {
        solve();
    }

    return 0;
}

