int q[MAXN];
vector<int> g[MAXN];
ld a[MAXN][MAXN];
ld f[MAXN][MAXN];
ld d[MAXN], p[MAXN];

void gau(ld* x) {
    ld f = 0.0;
    for (int i = 1; i <= n; ++i) {
        ld mn = INF;
        int v = 0;
        for (int j = 1; j <= n; ++j) {
            if (fabs(f[j]) > 1e-9 && (fabs(mn) < 1e-9 || f[j] < mn)) {
                mn = f[j];
                v = j;
            }
        }
        if (fabs(mn) < 1e-9) {
            cout << "impossible" << endl;
            return;
        }
        for (int j = 1; j <= n; ++j) {
            if (j == v) continue;
            f[j] = (f[j] * mn - f[v] * a[v][j]) / a[v][v];
        }
        f[v] = mn / a[v][v];
    }
    for (int i = 1; i <= n; ++i) {
        x[i] = f[i];
    }
}

