#include <stack>

using namespace std;

int largestRectangleArea(vector<int>& heights) {
    stack<int> s;
    int maxArea = 0;
    heights.push_back(0);
    for (int i = 0; i < heights.size(); ) {
        if (s.empty() || heights[s.top()] <= heights[i]) {
            s.push(i++);
        } else {
            int top = s.top();
            s.pop();
            maxArea = max(maxArea, heights[top] * (s.empty() ? i : i - s.top() - 1));
        }
    }
    return maxArea;
}

int main() {
