    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            heights[j] = matrix[i][j] == 0 ? heights[j] + 1 : 0;
        }
        maxArea = max(maxArea, largestRectangleArea(heights));
    }
    cout << maxArea << endl;
    return 0;
}

#include<iostream>
