    bitset<MAX_N> cur;
    for (int mask = 0; mask < (1 << n); mask++) {
        cur.reset();
        int tmp = 0;
        for (int i = 1; i <= n; i++) {
            if (mask & (1 << (i - 1))) {
                cur |= a[i];
