long long dist(int x, int y) {
    if (x <= y) return sumd - sumd * (y - x) / n;
    return sumd * (n - y + x) / n;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;
    for (int i = 0; i < n; ++i) {
