void dfs(int v, int p, vector<int> &sz) {
    sz[v] = 1;
    for (int u : g[v]) {
        if (u != p) {
            dfs(u, v, sz);
            sz[v] += sz[u];
        }
    }
}

int bfs(int v) {
    vector<int> dist(n + 1, 0);
    vector<int> sz(n + 1, 0);
    sz[v] = 1;
    dist[v] = 1;
    queue<int> q;
    q.push(v);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int p : g[u]) {
            if (dist[p] == 0) {
                dist[p] = dist[u] + 1;
                sz[p] = 1 + n / 2;
                q.push(p);
            }
        }
    }
    return *max_element(sz.begin(), sz.end());
}

