const unsigned long long mod = (1ULL << 58);

unsigned long long powmod(unsigned long long a, unsigned long long b, unsigned long long mod) {
    unsigned long long res = 1;
    while (b) {
        if (b & 1) {
            res = (res * a) % mod;
        }
        a = (a * a) % mod;
        b >>= 1;
    }
