                break;
            }
        }
        for (int i = j - 1; i >= 0; i--) {
            long long pos = p[i];
            pos -= HowMany;
            if ((pos - 1) / k < page) {
                p[i] = pos;
            } else {
                break;
            }
        }
        sort(p.begin(), p.begin() + m);
    }

    cout << ans << endl;

