            cnt[i]--;
        }
    }
    return ans;
}

string extend_to_max_zeros(int tot_zeros, string s) {
    string ans = "";
    if (tot_zeros == 0) {
        ans += s[0];
        string tmp = s.substr(1);
        while (tmp.size() > 0) {
            for (int i = 9; i >= 0; i--) {
