                    ans += to_string(i);
                    tmp.erase(tmp.find(to_string(i)), 1);
                    break;
                }
            }
        }
    } else {
        ans = s.substr(0, s.size() - tot_zeros);
        for (int i = 0; i < tot_zeros; i++) {
            ans += "0";
        }
    }
    return ans;
}

