bool check(long long mid) {
    int sum = 0;
    for (int i = n; i >= 1; i--) {
        vector<long long> dp(m + 1, 1e18);
        dp[0] = 0;
        for (auto& c : cat[i]) {
            for (int j = m; j >= 1; j--) {
                dp[j] = min(dp[j], dp[j - 1] + max(0LL, mid - c.second));
            }
        }
        sum += dp[m];
        if (pos[i] != 0) mid += pos[i];
    }
    return sum <= mid;
}

